const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => value == null ? 'Price not listed' : new Intl.NumberFormat('en-CH',{style:'currency',currency:'CHF',maximumFractionDigits:2}).format(value);
const usdMoney = value => value == null ? 'Price unavailable' : new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(value);
const eurMoney = value => value == null ? 'Price unavailable' : new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(value);
const stamp = value => value ? new Date(value).toLocaleString('en-CH',{dateStyle:'medium',timeStyle:'short'}) : 'Update time unavailable';
const getCategory = id => CATEGORIES.find(c=>c.id===id);
const CAT_GROUPS = ['PC Components','Gaming Peripherals','Displays','Gaming Furniture','PC & Streaming Extras'];
const icons = ['◈','⌘','▦','▧','▤','ϟ','▱','◉','✣','⌖','⌨','◖','▰','◉','◍','◌','▣','▥','◉','▱','⊞','✧','✦'];
