function persist(){writeState(state)}
function indexCatalogProducts(){productsByCategory=new Map();productsById=new Map();for(const product of catalog.products){productsById.set(product.id,product);const group=productsByCategory.get(product.category)||[];group.push(product);productsByCategory.set(product.category,group)}}
function tell(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function showPage(name){activePage=name;$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));if(name==='compare')renderComparison();if(name==='favorites')renderFavorites();if(name==='builder')renderBuild();$('#main-content').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'})}
function vendorMatches(product,vendor){const text=`${product.brand||''} ${product.name||''} ${product.model||''} ${product.specs?.manufacturer||''} ${product.specs?.gpuChipset||''}`.toLowerCase();const patterns={AMD:/\bamd\b|advanced micro devices|\bati\b|radeon|ryzen/,NVIDIA:/nvidia|geforce|quadro/,Intel:/intel|core ultra|core i[3579]|intel arc|\barc\b/};return patterns[vendor]?.test(text)||text.includes(vendor.toLowerCase())}

function renderCategories(){
  $('#category-nav').innerHTML=CAT_GROUPS.map(group=>`<div class="category-group"><div class="category-group-title">${esc(group)} <span>${CATEGORIES.filter(c=>c.group===group).length}</span></div>${CATEGORIES.filter(c=>c.group===group).map(c=>`<button data-category="${esc(c.id)}" class="${selectedCategory===c.id?'selected':''}"><span class="category-symbol">${icons[CATEGORIES.indexOf(c)]||'◈'}</span>${esc(c.label)}<span class="side-count">${productsByCategory.get(c.id)?.length||''}</span></button>`).join('')}</div>`).join('');
  $('#quick-categories').innerHTML=[['graphics-cards','Graphics cards','GPU picks','◈'],['gaming-mice','Gaming mice','Aim better','⌖'],['gaming-monitors','Gaming monitors','See every frame','▣'],['gaming-keyboards','Keyboards','Find your feel','⌨'],['processors','Processors','Power your play','ϟ'],['builder','Build my PC','Plan a full setup','＋']].map(([id,label,sub,icon])=>`<button class="quick-card" ${id==='builder'?'data-page="builder"':`data-category="${id}"`}><span class="qc-icon">${icon}</span><b>${label}</b><small>${sub}</small></button>`).join('');
  $('#all-count').textContent=catalog.products.length;
}

function currentFilters(){
  const filters={};
  for(const [key,range] of Object.entries(filterState)) {
    if(range&&typeof range==='object'){
      if(range.min<=range.low&&range.max>=range.high)continue;
      if(key==='priceCHF'){if(range.min>range.low)filters.minPrice=range.min;if(range.max<range.high)filters.maxPrice=range.max}
      else filters[key]={min:range.min,max:range.max};
    } else if(range!==undefined&&range!=='') filters[key]=range;
  }
  return filters;
}
function categoryProducts(){const result=selectedCategory?(productsByCategory.get(selectedCategory)||[]):catalog.products;return filterProducts(searchProducts(result,query),null,currentFilters())}
function renderFilters(){
  const category=getCategory(selectedCategory);const budget=rangeBounds.priceCHF;const controls=[];const filterCatalog=selectedCategory?(productsByCategory.get(selectedCategory)||[]):catalog.products;
  function rangeControl(key,label,low,high,step=1){let r=filterState[key]||{low,high,min:low,max:high};filterState[key]=r;controls.push(`<div class="filter-group"><div class="filter-group-title">${esc(label)}</div><div class="range-pair"><label>Min <input data-range="${key}" data-edge="min" type="range" min="${low}" max="${high}" step="${step}" value="${r.min}"><span class="range-value">${r.min}</span></label><label>Max <input data-range="${key}" data-edge="max" type="range" min="${low}" max="${high}" step="${step}" value="${r.max}"><span class="range-value">${r.max}</span></label></div></div>`)}
  const priceRange=numericBounds(filterCatalog,null,'priceCHF',budgets[selectedCategory]||rangeBounds.priceCHF||[0,1500,10]);rangeControl('priceCHF','Budget · CHF',priceRange[0],priceRange[1],priceRange[2]);
  for(const f of category?.filters||[]){
    if(f.type==='number') {const [lo,hi,step]=numericBounds(filterCatalog,null,f.key,rangeBounds[f.key]||[0,1000,10]);rangeControl(f.key,f.label,lo,hi,step);continue}
    if(f.key==='wireless'){controls.push(`<div class="filter-group"><label class="filter-group-title" for="filter-wireless">Wireless</label><select id="filter-wireless" class="filter-select" data-select="wireless"><option value="">Any</option><option value="true" ${filterState.wireless===true?'selected':''}>Wireless</option><option value="false" ${filterState.wireless===false?'selected':''}>Wired</option></select></div>`);continue}
    if(f.type==='boolean'){controls.push(`<div class="filter-group"><div class="filter-group-title">${esc(f.label)}</div><label class="check-row"><input type="checkbox" data-check="${esc(f.key)}" ${filterState[f.key]?'checked':''}> Yes only</label></div>`);continue}
    const opts=selectOptions(filterCatalog,null,f.key);controls.push(`<div class="filter-group"><label class="filter-group-title" for="filter-${esc(f.key)}">${esc(f.label)}</label><select id="filter-${esc(f.key)}" class="filter-select" data-select="${esc(f.key)}"><option value="">Any</option>${opts.map(o=>`<option value="${esc(o)}" ${filterState[f.key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`);
  }
  const title=category?`${category.label} filters`:'Filter all products';
  $('#filters').innerHTML=`<div class="filter-heading"><span>${esc(title)}</span><button id="reset-filters">Reset all</button></div><div class="filter-groups">${controls.join('')}</div><button id="apply-filters" class="primary-button apply-button">Apply filters</button>`;
  $('#filters').querySelectorAll('[data-range]').forEach(input=>input.addEventListener('input',()=>{let r=filterState[input.dataset.range];r[input.dataset.edge]=Number(input.value);if(r.min>r.max){if(input.dataset.edge==='min')r.max=r.min;else r.min=r.max}input.parentElement.querySelector('.range-value').textContent=input.value}));
  $('#filters').querySelectorAll('[data-check]').forEach(input=>input.addEventListener('change',()=>{filterState[input.dataset.check]=input.checked||undefined}));
  $('#filters').querySelectorAll('[data-select]').forEach(input=>input.addEventListener('change',()=>{filterState[input.dataset.select]=input.dataset.select==='wireless'?(input.value===''?undefined:input.value==='true'):(input.value||undefined)}));
  $('#reset-filters').onclick=()=>{filterState={};renderFilters();renderProducts()};$('#apply-filters').onclick=renderProducts;
}

function specLabel(key){const names={manufacturer:'Manufacturer',vramGB:'VRAM (GB)',gpuChipset:'GPU chipset',powerW:'Power (W)',lengthMM:'Length (mm)',gpuClearanceMM:'GPU clearance (mm)',cpuCoolerClearanceMM:'Cooler clearance (mm)',baseClockMHz:'Base clock (MHz)',coreClockMHz:'Core clock (MHz)',boostClockMHz:'Boost clock (MHz)',frequencyMHz:'Memory speed (MT/s)',refreshRateHz:'Refresh rate (Hz)',memoryBusBits:'Memory bus (bits)',readMBps:'Read (MB/s)',writeMBps:'Write (MB/s)',deviceClass:'Device class',releaseYear:'Release year',generation:'Generation',architecture:'Architecture',maxMemoryGB:'Max memory (GB)',memorySlots:'Memory slots',memoryType:'Memory type',pcieGeneration:'PCIe generation',m2Slots:'M.2 slots',supportedFormFactors:'Supported form factors',chipsets:'Chipsets',socket:'CPU socket',socketModelFamily:'CPU socket (model family)',cores:'Cores',threads:'Threads',formFactor:'Form factor',capacityGB:'Capacity (GB)',efficiency:'Efficiency'};return names[key]||key.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())}
function productSpecs(p){const specs={...(p.specs||{})};if(p.category==='processors'&&!specs.socket)specs.socketModelFamily=cpuSocket(p);const entries=Object.entries(specs).filter(([,v])=>v!=null&&typeof v!=='object'&&v!=='manufacturer');const priorities={'graphics-cards':['vramGB','gpuChipset','architecture','powerW','memoryType','pcieGeneration','lengthMM'],'processors':['socket','socketModelFamily','generation','architecture','cores','threads','boostClockMHz','powerW'],'motherboards':['socket','chipset','pcieGeneration','memoryType','maxMemoryGB','formFactor'],'ram':['capacityGB','memoryType','frequencyMHz','modules'],'storage':['capacityGB','readMBps','writeMBps','interface'],'power-supplies':['powerW','efficiency','formFactor'],'cases':['supportedFormFactors','formFactor','gpuClearanceMM','cpuCoolerClearanceMM'],'cpu-coolers':['supportedSockets','coolerType','heightMM','noiseDB']};const priority=priorities[p.category]||['refreshRateHz'];const selected=priority.flatMap(key=>entries.filter(([k])=>k===key)).concat(entries.filter(([key])=>!priority.includes(key))).slice(0,3);return selected.map(([k,v])=>`<span class="spec-pill">${esc(specLabel(k))}: ${esc(v)}</span>`).join('')||'<span class="spec-pill">Specifications not listed</span>'}
function priceDisclosure(p){if(p.priceCHF==null)return `<p>No dated price is listed for this model. Use the Digitec search to check current Swiss listings; a result may be a different model variant.</p><small>Specifications and product details are shown from the cited catalog source.</small>`;if(p.priceType==='eu-reference')return `<p>France-market snapshot ${eurMoney(p.priceEUR)} · published ${esc(p.priceDate)}. Displayed as ${money(p.priceCHF)} using the ECB rate from ${esc(p.fxDate)} (1 EUR = ${esc(p.fxRate)} CHF).</p><small>${esc(p.availability||'Current stock not represented')} · <a href="${esc(p.priceSourceUrl)}" target="_blank" rel="noopener noreferrer">Dataset source ↗</a> · <a href="https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html" target="_blank" rel="noopener noreferrer">ECB reference rates ↗</a></small>`;if(p.priceType==='docyx-us-reference')return `<p>US reference ${usdMoney(p.priceUSD)} · published ${esc(p.priceDate)}. Displayed as ${money(p.priceCHF)} using the ECB rate from ${esc(p.fxDate)} (1 USD = ${esc(p.fxRate)} CHF).</p><small>${esc(p.availability||'Current stock not represented')} · <a href="${esc(p.priceSourceUrl)}" target="_blank" rel="noopener noreferrer">Dataset source ↗</a> · <a href="https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html" target="_blank" rel="noopener noreferrer">ECB reference rates ↗</a></small>`;if(p.priceType!=='us-reference')return `<p>${p.availability?esc(p.availability):'Availability unavailable'} · ${esc(p.source||catalog.source)}</p>`;return `<p>US typical ${usdMoney(p.priceUSD)} · ${esc(p.priceWeek)}. Displayed as ${money(p.priceCHF)} using the ECB rate from ${esc(p.fxDate)} (1 USD = ${esc(p.fxRate)} CHF).</p><small>${esc(p.availability||'US stock unavailable')} · <a href="${esc(p.priceSourceUrl)}" target="_blank" rel="noopener noreferrer">Price source ↗</a> · <a href="https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html" target="_blank" rel="noopener noreferrer">ECB reference rates ↗</a></small>`}
