function renderBuild(){
  const budget=Number($('#build-budget').value);
  $('#build-budget-number').value=budget;
  $('#budget-value').textContent=money(budget);
  const priority=$('#build-priority').value;
  const labels={gpu:'Graphics card',cpu:'Processor',motherboard:'Motherboard',ram:'Memory',storage:'Storage',psu:'Power supply',case:'Case',cooling:'CPU cooler'};
  const categoryMap={gpu:'graphics-cards',cpu:'processors',motherboard:'motherboards',ram:'ram',storage:'storage',psu:'power-supplies',case:'cases',cooling:'cpu-coolers'};
  const preferredGPU=$('#build-gpu').value,preferredCPU=$('#build-cpu').value,game=$('#build-game').value,focus=$('#build-focus').value;
  const focusMode=focus==='competitive'||$('#build-fps').value==='240 FPS'||/counter-strike|valorant|apex|overwatch|rainbow six/i.test(game)?'esports':focus==='visual'||$('#build-resolution').value==='4K'?'performance':focus==='value'?'budget':'overall';
  const priorityParts=priority==='memory'?['ram','storage']:priority==='balanced'?[]:[priority];
  const weights=(values={})=>({...values,...Object.fromEntries(priorityParts.map(part=>[part,1.7]))});
  const plans=[
    {id:'balanced',name:'Balanced',description:'Builds a well-rounded gaming PC and uses nearly all of your budget.',useCase:focusMode,weights:weights({gpu:1.35,cpu:1.2,motherboard:.8,ram:.9,storage:.8,psu:.8,case:.65,cooling:.6})},
    {id:'value',name:'Best value',description:'Prioritizes useful performance while keeping the full build close to your budget.',useCase:'budget',weights:weights({gpu:1.25,cpu:1.1,motherboard:.9,ram:.95,storage:.9,psu:.8,case:.7,cooling:.65})},
    {id:'graphics',name:'Graphics first',description:'Puts the largest performance priority on the graphics card.',useCase:focusMode==='esports'?'esports':'performance',weights:weights({gpu:2,cpu:1,motherboard:.7,ram:.8,storage:.75,psu:.8,case:.6,cooling:.55})},
    {id:'processor',name:'Processor first',description:'Prioritizes the processor for CPU-heavy games and multitasking.',useCase:'performance',weights:weights({gpu:1,cpu:2,motherboard:.95,ram:.9,storage:.75,psu:.8,case:.6,cooling:.75})},
    {id:'high-fps',name:focusMode==='esports'?'High-FPS build':'Maximum performance',description:'Ranks the full system for the frame-rate and resolution targets you chose.',useCase:focusMode==='esports'?'esports':'performance',weights:weights({gpu:1.6,cpu:1.55,motherboard:.8,ram:.9,storage:.7,psu:.8,case:.55,cooling:.7})}
  ];
  const eligibleByPart={};
  for(const [part,category] of Object.entries(categoryMap)){
    let eligible=(productsByCategory.get(category)||[]).filter(p=>p.priceCHF!=null&&p.priceCHF<=budget);
    if(part==='gpu'&&preferredGPU!=='Any')eligible=eligible.filter(p=>vendorMatches(p,preferredGPU));
    if(part==='cpu'&&preferredCPU!=='Any')eligible=eligible.filter(p=>vendorMatches(p,preferredCPU));
    if(part==='gpu'){const minimumVRAM=$('#build-resolution').value==='4K'?12:$('#build-resolution').value==='1440p'?8:6;const capable=eligible.filter(p=>typeof p.specs?.vramGB==='number'&&p.specs.vramGB>=minimumVRAM);if(capable.length)eligible=capable}
    if(part==='cpu')eligible=eligible.filter(p=>cpuSocket(p));
    if(part==='case'&&$('#build-style').value==='RGB showcase'){const rgb=eligible.filter(p=>p.specs?.rgb===true);if(rgb.length)eligible=rgb}
    if(part==='case'&&$('#build-style').value==='Compact build'){const compact=eligible.filter(p=>/mini|itx/i.test(p.specs?.formFactor||p.name));if(compact.length)eligible=compact}
    if(['case','cooling'].includes(part)&&$('#build-style').value==='Quiet and understated'){const quiet=eligible.filter(p=>typeof p.specs?.noiseDB==='number');if(quiet.length)eligible=quiet}
    eligibleByPart[part]=eligible;
  }
  const buildCacheKey=JSON.stringify({catalog:catalog.updatedAt,source:catalog.source,count:catalog.products.length,budget,priority,preferredGPU,preferredCPU,game,focus:$('#build-focus').value,fps:$('#build-fps').value,focusMode,resolution:$('#build-resolution').value,style:$('#build-style').value,planSelections:builderPlanSelections});
  let planResults=builderResultCache.get(buildCacheKey);
  if(!planResults){
  const rankCache=new Map();
  planResults=plans.map(plan=>{
    const selections=builderPlanSelections[plan.id]||(builderPlanSelections[plan.id]={}),rankedParts={};
    for(const part of Object.keys(categoryMap)){
      const cacheKey=`${part}:${plan.useCase}`;
      if(!rankCache.has(cacheKey))rankCache.set(cacheKey,rankProducts(eligibleByPart[part],plan.useCase));
      rankedParts[part]=rankCache.get(cacheKey);
      if(selections[part]&&!rankedParts[part].some(option=>option.product.id===selections[part]))delete selections[part];
    }
    let optimized=optimizeBuild(rankedParts,budget,plan.weights,selections);
    if(!optimized.complete&&Object.keys(selections).length){for(const part of Object.keys(selections))delete selections[part];optimized=optimizeBuild(rankedParts,budget,plan.weights,selections)}
    return {plan,rankedParts,selections:{...selections},build:optimized.build,checks:optimized.checks,total:optimized.total,quality:optimized.quality,complete:optimized.complete,verified:optimized.verified,verificationGaps:optimized.verificationGaps||[],withinBudget:optimized.withinBudget,missingParts:optimized.missingParts};
  });
  builderResultCache.set(buildCacheKey,planResults);
  if(builderResultCache.size>3)builderResultCache.delete(builderResultCache.keys().next().value);
  }
  lastBuildResults=planResults;
  activeBuildIndex=Math.min(planResults.length-1,Math.max(0,activeBuildIndex));
  const active=planResults[activeBuildIndex];
  active.optionsByPart={};
  for(const part of Object.keys(categoryMap)){
    const ranked=active.rankedParts[part]||[];
    const candidateIds=new Set(ranked.slice(0,12).map(option=>option.product.id));
    if(active.build[part])candidateIds.add(active.build[part].id);
    const viable=[];
    for(const id of candidateIds){
      const candidate=ranked.find(option=>option.product.id===id);
      if(!candidate)continue;
      if(!active.complete||!active.build[part])continue;
      const alternative={...active.build,[part]:candidate.product};
      const total=active.total-active.build[part].priceCHF+candidate.product.priceCHF;
      if(total>budget+0.005)continue;
      const checks=buildCompatibilityChecks(alternative);
      if(checks.some(check=>check.status==='incompatible'))continue;
      const unknownChecks=checks.filter(check=>check.status==='unknown');
      viable.push({...candidate,completeBuildTotal:total,completeBuildQuality:candidate.score,unknownChecks});
    }
    viable.sort((a,b)=>b.completeBuildQuality-a.completeBuildQuality||a.unknownChecks.length-b.unknownChecks.length||b.score-a.score||b.completeBuildTotal-a.completeBuildTotal);
    active.optionsByPart[part]=viable;
  }
  const missing=active.missingParts.map(part=>labels[part]);
  const optionMarkup=Object.entries(active.optionsByPart).map(([part,options])=>`<section class="build-slot"><div class="build-slot-heading"><div><h3>${labels[part]}</h3><small>${options.length} full-build-compatible options · selected part uses ${active.build[part]?money(active.build[part].priceCHF):'no budget'}</small></div><b>${active.build[part]?money(active.build[part].priceCHF):'No priced options'}</b></div>${options.length?`<div class="build-options">${options.map(option=>{const p=option.product,selected=active.build[part]?.id===p.id;const status=p.priceType==='us-reference'?`US price ${usdMoney(p.priceUSD)} · ${esc(p.priceWeek)}`:p.priceType==='eu-reference'?`France price ${eurMoney(p.priceEUR)} · ${esc(p.priceDate)}`:p.priceType==='docyx-us-reference'?`US reference ${usdMoney(p.priceUSD)} · ${esc(p.priceDate)}`:'Price source dated';const fit=option.unknownChecks.length?`No known conflicts · ${option.unknownChecks.length} checks unverified · full build ${money(option.completeBuildTotal)}`:`All compatibility checks pass · full build ${money(option.completeBuildTotal)}`;return `<label class="build-option ${selected?'is-selected':''}"><input type="radio" name="build-${part}" data-build-choice="${part}" data-build-plan="${active.plan.id}" value="${esc(p.id)}" ${selected?'checked':''}><span class="build-option-image">${imageMarkup(p)}</span><span class="build-option-copy"><b>${esc(p.brand||'Brand not listed')}</b><strong>${esc(p.model||p.name)}</strong><span class="spec-pills">${productSpecs(p)}</span><small>${status}</small><small class="build-fit-status">${fit}</small><em>${money(p.priceCHF)}${selected?' · In this build':''}</em></span></label>`}).join('')}</div>`:'<p class="build-empty">No priced option for this slot can complete a compatible build with the current choices.</p>'}</section>`).join('');
  const planButtons=planResults.map((result,index)=>`<button type="button" class="build-plan-dot ${index===activeBuildIndex?'active':''}" data-plan-index="${index}" aria-label="Show ${esc(result.plan.name)} build, estimated ${result.complete?money(result.total):'not available'}"><span>${esc(result.plan.name)}</span><b>${result.complete?money(result.total):'No build'}</b></button>`).join('');
  const buildStatus=active.complete?'COMPLETE · NO KNOWN CONFLICTS':'NO COMPLETE BUILD';
  const estimatedTotal=active.complete?money(active.total):'—';
  const unknownCount=active.checks.filter(check=>check.status==='unknown').length;
  const buildSummary=active.complete?`${money(Math.max(0,budget-active.total))} left under your ${money(budget)} budget · ${esc(active.plan.description)}${unknownCount?` · ${unknownCount} fit checks need source data`:''}`:active.missingParts.length?`No complete build fits this budget and preference set.`:'No build is available for this plan.';
  const warning=active.complete&&unknownCount?`No known incompatibilities. ${unknownCount} checks are unverified because the catalog does not publish the required fit details; confirm these before buying.`:missing.length?`No complete build is available for: ${missing.map(esc).join(', ')}.`:'';
  const confirmedChecks=active.checks.filter(check=>check.status==='compatible');
  const unverifiedChecks=active.checks.filter(check=>check.status==='unknown');
  $('#build-result').innerHTML=`<div class="build-slider-top"><button type="button" class="build-step-button" data-plan-step="-1" aria-label="Previous build">‹</button><label for="build-plan-slider"><span>BUILD OPTION <b id="build-plan-count">${activeBuildIndex+1} / ${plans.length}</b></span><input id="build-plan-slider" type="range" min="0" max="${plans.length-1}" step="1" value="${activeBuildIndex}" aria-label="Choose a complete PC build"></label><button type="button" class="build-step-button" data-plan-step="1" aria-label="Next build">›</button></div><div class="build-plan-dots">${planButtons}</div><div class="build-summary"><div><small>${esc(active.plan.name.toUpperCase())} · ${buildStatus}</small><h2>Estimated total <strong>${estimatedTotal}</strong></h2><p>${buildSummary}</p></div><span class="build-option-count">${Object.values(active.optionsByPart).reduce((sum,items)=>sum+items.length,0)} compatible part options</span></div>${warning?`<p class="build-warning">${warning}</p>`:''}<div class="build-slot-list">${optionMarkup}</div><section class="compat-list"><b>Confirmed compatibility checks</b>${confirmedChecks.length?confirmedChecks.map(check=>`<div class="compat-row"><span class="compat-status compatible"></span><span><b>${esc(check.check)} · compatible:</b> ${esc(check.detail)}</span></div>`).join(''):'<p class="compat-empty">No compatibility checks can be confirmed for this selection.</p>'}</section>${unverifiedChecks.length?`<section class="compat-unverified"><b>Catalog details still needed</b><p>These checks stay unmarked until the source lists enough detail to confirm them:</p><ul>${unverifiedChecks.map(check=>`<li>${esc(check.check)}</li>`).join('')}</ul></section>`:''}<div class="product-source">Known incompatible parts are excluded. A green check means the listed specifications confirm a match; unverified details are shown separately.</div>`;
}

function updateBanner(){const imported=catalog.products.length>0;$('#data-status').textContent=catalog.kind==='builtin-public'?`${catalog.products.length} built-in products · dated US/EU prices converted to CHF where available · not Swiss store listings · ${stamp(catalog.updatedAt)}`:imported?`${catalog.products.length} imported products · ${catalog.source} · Last update ${stamp(catalog.updatedAt)}`:'Local catalog · No live Digitec feed connected';$('#data-banner .status-dot').style.background=imported?'var(--green)':'#e5ad5e'}
async function loadCatalog(){try{catalog=await getProvider().load();}catch{catalog={source:'No catalog connected',updatedAt:null,products:[]}}try{const local=localStorage.getItem('gamegear-hub-import');if(local){const saved=parseCatalog(local);if(saved.products.length)catalog=saved}}catch{tell('The saved catalog could not be read. Re-import a valid JSON catalog.')}indexCatalogProducts();builderResultCache.clear();updateBanner();renderProducts();renderBuild()}

document.addEventListener('click',e=>{const page=e.target.closest('button[data-page]');if(page){if(page.classList.contains('side-home')){selectedCategory=null;filterState={};renderProducts()}showPage(page.dataset.page)}});
$('#category-nav').addEventListener('click',e=>{const button=e.target.closest('[data-category]');if(!button)return;selectedCategory=button.dataset.category;filterState={};showPage('catalog');renderProducts()});
$('#quick-categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b){selectedCategory=b.dataset.category;filterState={};renderProducts()}if(e.target.closest('[data-page="builder"]'))showPage('builder')});
$('#sort-select').onchange=renderProducts;
$('#load-more-products').onclick=()=>{visibleLimit+=30;renderProducts(true)};
$('#usecase-select').onchange=renderProducts;
$('#global-search').addEventListener('input',e=>{query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{renderProducts();const matches=searchProducts(catalog.products,query).slice(0,5);$('#search-suggestions').innerHTML=matches.map(p=>`<button data-suggest="${esc(p.id)}">${esc(p.name)} <small>· ${esc(p.brand||p.category)}</small></button>`).join('');$('#search-suggestions').hidden=!query||!matches.length},130)});
$('#search-suggestions').addEventListener('click',e=>{const b=e.target.closest('[data-suggest]');if(!b)return;const p=productsById.get(b.dataset.suggest);selectedCategory=p.category;$('#global-search').value=p.name;query=p.name;$('#search-suggestions').hidden=true;renderProducts()});
document.addEventListener('click',e=>{if(!e.target.closest('.top-search'))$('#search-suggestions').hidden=true});document.addEventListener('keydown',e=>{const image=e.target.closest?.('[data-image]');if(image&&(e.key==='Enter'||e.key===' ')){e.preventDefault();showProductImage(image.dataset.image);return}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape')$('#search-suggestions').hidden=true});
$('#theme-toggle').onclick=()=>{state={...state,theme:state.theme==='dark'?'light':'dark'};document.documentElement.dataset.theme=state.theme;persist()};document.documentElement.dataset.theme=state.theme;
$('#favorites-shortcut').onclick=()=>showPage('favorites');$('#open-compare').onclick=()=>showPage('compare');$('#clear-compare').onclick=()=>{state={...state,comparison:[]};persist();renderDock();renderProducts()};
$('#build-budget').addEventListener('input',e=>{$('#build-budget-number').value=e.target.value;$('#budget-value').textContent=money(Number(e.target.value))});
$('#build-budget').addEventListener('change',()=>{builderResultCache.clear();renderBuild()});
$('#build-budget-number').addEventListener('input',e=>{const value=Number(e.target.value);if(value>=300&&value<=20000){$('#build-budget').value=value;$('#budget-value').textContent=money(value)}});
$('#build-budget-number').addEventListener('change',e=>{const value=Math.min(20000,Math.max(300,Number(e.target.value)||300));$('#build-budget').value=value;builderResultCache.clear();renderBuild()});
['build-resolution','build-fps','build-focus','build-gpu','build-cpu','build-game','build-style','build-priority'].forEach(id=>$('#'+id).addEventListener('change',renderBuild));
$('#build-result').addEventListener('input',e=>{if(e.target.id!=='build-plan-slider')return;activeBuildIndex=Number(e.target.value);renderBuild()});
$('#build-result').addEventListener('change',e=>{const choice=e.target.closest('[data-build-choice]');if(!choice)return;const planSelections=builderPlanSelections[choice.dataset.buildPlan]||(builderPlanSelections[choice.dataset.buildPlan]={});const prior=planSelections[choice.dataset.buildChoice];planSelections[choice.dataset.buildChoice]=choice.value;renderBuild();const plan=lastBuildResults.find(result=>result.plan.id===choice.dataset.buildPlan);if(!plan?.complete||!plan.withinBudget||plan.build[choice.dataset.buildChoice]?.id!==choice.value){if(prior)planSelections[choice.dataset.buildChoice]=prior;else delete planSelections[choice.dataset.buildChoice];renderBuild();tell('That part cannot form a complete compatible build under this budget.')}});
$('#build-result').addEventListener('click',e=>{const dot=e.target.closest('[data-plan-index]'),step=e.target.closest('[data-plan-step]');if(!dot&&!step)return;activeBuildIndex=dot?Number(dot.dataset.planIndex):Math.min(4,Math.max(0,activeBuildIndex+Number(step.dataset.planStep)));renderBuild()});
$('#builder-form').onsubmit=e=>{e.preventDefault();renderBuild();tell('Part options refreshed · compatibility reflects known specifications only')};
document.addEventListener('click',e=>{const image=e.target.closest('[data-image]');if(image){e.preventDefault();e.stopPropagation();showProductImage(image.dataset.image);return}const favorite=e.target.closest('[data-favorite]');if(favorite){state=toggleFavorite(state,favorite.dataset.favorite);persist();renderDock();if(activePage==='favorites')renderFavorites();else renderProducts();return}const details=e.target.closest('[data-details]');if(details){openProductDetails(details.dataset.details);return}const target=e.target.closest('[data-target]');if(target){const id=target.dataset.target;const current=state.targets[id];const answer=prompt(current?`Current target: CHF ${current}. Enter a new CHF target or leave blank to remove it.`:'Set a target price in CHF:');if(answer===null)return;if(answer.trim()===''){const targets={...state.targets};delete targets[id];state={...state,targets};tell('Price target removed')}else{const value=Number(answer);if(!Number.isFinite(value)||value<0){tell('Enter a valid non-negative CHF amount');return}state={...state,targets:{...state.targets,[id]:value}};tell('Price target saved on this device')}persist();if(activePage==='favorites')renderFavorites();else renderProducts();return}const compare=e.target.closest('[data-compare]');if(compare){const id=compare.dataset.compare;if(state.comparison.includes(id))state={...state,comparison:state.comparison.filter(x=>x!==id)};else{const next=addCompare(state,id);if(next===state){tell('Comparison is full · remove an item first');return}state=next}persist();renderDock();if(activePage==='compare')renderComparison();else renderProducts()}});
$('#import-open').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{let imported=parseCatalog(await file.text());imported={...imported,source:imported.source==='No catalog connected'?file.name:imported.source};catalog=imported;indexCatalogProducts();builderResultCache.clear();let persisted=true;try{localStorage.setItem('gamegear-hub-import',JSON.stringify(catalog))}catch{persisted=false}selectedCategory=null;filterState={};updateBanner();renderProducts();tell(persisted?`Imported ${catalog.products.length} products`:`Imported ${catalog.products.length} products for this session; browser storage is unavailable`)}catch(err){tell(err.message||'Could not import this catalog')}e.target.value=''};
$('#export-button').onclick=()=>{const blob=new Blob([JSON.stringify(catalog,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='gamegear-hub-catalog.json';a.click();URL.revokeObjectURL(a.href)};
$('#recent-section').hidden=true;
loadCatalog();

